// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    OwnerBeneficiary helper;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function testFuzz_property(uint256 amount, bool forwardBack) public {
        amount = bound(amount, 0, 1 ether);

        helper = new OwnerBeneficiary(address(c));

        address owner = c.Owner();
        vm.deal(owner, 0);

        vm.deal(address(helper), amount);

        vm.deal(address(this), amount);

        vm.prank(owner);
        c.Command{value: amount}(address(helper), "");

        if (!forwardBack) {
            helper.setForward(false);

            assertTrue(address(owner).balance == 0);
        } else {
            assertTrue(address(c).balance == 0);
        }
    }
}

contract OwnerBeneficiary {
    address public targetC;
    bool public forwardToOwner = false;

    constructor(address _c) payable {
        targetC = _c;
    }

    function setForward(bool f) public {
        forwardToOwner = f;
    }

    fallback() external payable {
        if (forwardToOwner && msg.value > 0) {
            (bool ok, bytes memory data) = targetC.call(abi.encodeWithSignature("Owner()"));
            if (ok && data.length >= 32) {
                address owner = abi.decode(data, (address));
                payable(owner).transfer(msg.value);
            }
        }
    }
}
